#!/usr/bin/env bash
# Removes the demo resource (the `assets` example) from a repo generated by go-react-starter,
# leaving the structure, the docs and a gate that still passes. Works in either layout:
# server/ + web/, or a --go-only repo with the module at the root.
#
#   scripts/strip-demo.sh            # this repo
#   scripts/strip-demo.sh <dir>      # another checkout of a generated repo
#
# It refuses to run twice: the second run has nothing to do and says so.
set -euo pipefail

ROOT="${1:-$(cd "$(dirname "$0")/.." && pwd)}"
cd "$ROOT"

fail() { echo "strip-demo: $1" >&2; exit 1; }

# the Go module lives in server/ in the full shape and at the root in --go-only
if [ -d server/internal/asset ]; then
  GO=server
elif [ -d internal/asset ]; then
  GO=.
else
  fail "no internal/asset here — already stripped?"
fi
export GO

# --- delete the resource
rm -rf "$GO/internal/asset"
rm -f "$GO/internal/httpapi/store.go" \
      "$GO/internal/httpapi/handlers.go" \
      "$GO/internal/httpapi/handlers_test.go"
rm -f testdata/asset.json
rmdir testdata 2>/dev/null || true
rm -f web/src/api/client.ts web/src/api/client.test.ts
rm -f web/src/components/asset-list.tsx web/src/components/asset-list.test.tsx
rm -f web/src/routes/assets.tsx web/src/routes/asset-detail.tsx

# --- router.go: New keeps the resource-free endpoints only
python3 - <<'PY'
import os, pathlib, sys

p = pathlib.Path(os.environ["GO"], "internal/httpapi/router.go")
src = p.read_text()
i = src.index("// New returns")
j = src.index("\n}\n", i) + 3  # end of New only; anything added below it survives
body = '''// New returns a ready handler: routes, logging, panic recovery.
func New(log *zap.Logger, ui http.Handler) http.Handler {
	a := &api{log: log}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", a.health)
	mux.HandleFunc("/api/", a.notFound)
	if ui != nil {
		mux.Handle("/", ui)
	} else {
		mux.HandleFunc("/", a.notFound)
	}

	return withLogging(log, withRecover(log, mux))
}
'''
if src[i:j] == body:
    sys.exit("router.go already has the demo-free New")
p.write_text(src[:i] + body + src[j:])
PY

# --- main.go: no store to build, no asset import
MAIN="$GO/cmd/app/main.go"
perl -ni -e 'print unless m{internal/asset}' "$MAIN"
perl -pi -e 's/httpapi\.New\(asset\.NewMemStore\(\), log, server\.UI\(\)\)/httpapi.New(log, server.UI())/' "$MAIN"
grep -q 'httpapi.New(log, server.UI())' "$MAIN" || fail "main.go was not edited"

# --- Dockerfile: the fixture it copied is gone (a --go-only image never copied it)
if [ -f Dockerfile ]; then
  perl -ni -e 'print unless m{COPY testdata /app/testdata}' Dockerfile
  if grep -q 'COPY testdata' Dockerfile; then fail "Dockerfile was not edited"; fi
fi

# --- web/src/router.tsx: the route tree is declared in code (absent in --go-only)
if [ -f web/src/router.tsx ]; then
python3 - <<'PY'
import pathlib, sys

p = pathlib.Path("web/src/router.tsx")
s = p.read_text()
before = s
s = s.replace("import { assetDetailRoute } from '@/routes/asset-detail'\n", "")
s = s.replace("import { assetsRoute } from '@/routes/assets'\n", "")
s = s.replace("rootRoute.addChildren([assetsRoute, assetDetailRoute])", "rootRoute.addChildren([])")
if s == before:
    sys.exit("router.tsx was not edited — has the route tree changed shape?")
p.write_text(s)
PY
fi

# --- root.tsx: the header link has no route left to point at
if [ -f web/src/routes/root.tsx ]; then
python3 - <<'PY'
import pathlib, sys

p = pathlib.Path("web/src/routes/root.tsx")
s = p.read_text()
before = s
s = s.replace("import { createRootRoute, Link, Outlet } from '@tanstack/react-router'",
              "import { createRootRoute, Outlet } from '@tanstack/react-router'")
s = s.replace("""        <Link to='/' className='text-lg font-semibold text-slate-900'>
          Assets
        </Link>""",
              """        <span className='text-lg font-semibold text-slate-900'>App</span>""")
if s == before:
    sys.exit("root.tsx was not edited")
p.write_text(s)
PY
fi

# --- README: a blank repo must not describe code it no longer has
python3 - <<'PY'
import pathlib, sys

p = pathlib.Path("README.md")
s = p.read_text()
before = s

i = s.find("## The demo resource is disposable")
if i != -1:
    j = s.find("\n## ", i + 3)
    s = s[:i] + (s[j + 1:] if j != -1 else "")

# both shapes mention the demo package somewhere in prose: the full README in its demo section
# (already cut above), the --go-only README in its layout block
s = s.replace("internal/asset", "internal/<domain>")
s = s.replace("scripts/    preflight.sh (the gate), dev.sh (both servers), scaffold.sh (new repo), strip-demo.sh",
              "scripts/    preflight.sh (the gate), dev.sh (both servers), scaffold.sh (new repo)")

if s == before:
    sys.exit("README.md was not edited — has the demo section moved?")
p.write_text(s)
PY

if command -v gofmt >/dev/null 2>&1; then gofmt -w "$GO" >/dev/null 2>&1 || true; fi

echo "strip-demo: demo removed from $ROOT"
echo "next: add your own internal/<domain>, then scripts/preflight.sh"